#!/usr/bin/env python3
"""
writer.py  -  Dream Wedding · zip "cabinet-v1"
Ports dreamai's "Your Books" cabinet (Cards / Workbench / Accounts) to the
wedding PWA as a theme-aware, read-only surface, and adds Flair as a genuine
third theme (dreamai navy/bone/ember) beside dark & light.

Idempotent and non-destructive: every file write checks a marker; every
in-place edit checks its anchor and SKIPs (with a warning) if the anchor is
missing or not unique - it never corrupts a file. Safe to re-run.

Run from the repo root (dreamos-pwa).
"""
import base64, os, sys

OK, SKIPm, NEW = "  ok  ", " SKIP ", " new  "
changed = 0
skipped = 0

def d(s):  # decode a base64 payload to text
    return base64.b64decode(s).decode("utf-8")

def write_file(path, b64, marker=None):
    global changed
    data = d(b64)
    if os.path.exists(path):
        cur = open(path, encoding="utf-8").read()
        if marker and marker in cur:
            print(SKIPm, path, "(already present)"); return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    open(path, "w", encoding="utf-8").write(data)
    print(NEW, path); changed += 1

def append_once(path, b64, marker):
    global changed, skipped
    if not os.path.exists(path):
        print(SKIPm, path, "(missing - cannot append)"); skipped += 1; return
    cur = open(path, encoding="utf-8").read()
    if marker in cur:
        print(SKIPm, path, "(append marker present)"); return
    open(path, "a", encoding="utf-8").write(d(b64))
    print(OK, path, "(appended cabinet css)"); changed += 1

def edit(path, anchor, replacement, label):
    """Replace exactly one unique occurrence of anchor. SKIP if missing/dup/done."""
    global changed, skipped
    if not os.path.exists(path):
        print(SKIPm, path, "(" + label + ": file missing)"); skipped += 1; return
    cur = open(path, encoding="utf-8").read()
    if replacement in cur:
        print(SKIPm, path, "(" + label + ": already applied)"); return
    n = cur.count(anchor)
    if n == 0:
        print(SKIPm, path, "(" + label + ": ANCHOR MISSING - not applied)"); skipped += 1; return
    if n != 1:
        print(SKIPm, path, "(" + label + ": anchor not unique x" + str(n) + " - not applied)"); skipped += 1; return
    open(path, "w", encoding="utf-8").write(cur.replace(anchor, replacement, 1))
    print(OK, path, "(" + label + ")"); changed += 1

def insert_before(path, anchor, block, label):
    edit(path, anchor, block + anchor, label)

# ---- payloads (base64) ------------------------------------------------------
B_CABINET_TSX = ""
B_CABINET_CSS = ""
B_USETHEME_TS = ""
B_VENDOR_INSERT = ""
B_FLAIR_BLOCK   = ""
B_VENDOR_ANCHOR = "Ly8g4pSA4pSAIENoYXQgaGlzdG9yeSAoMy4wLUI6IGRpc3BsYXktb25seSBzY3JvbGxiYWNrKQ=="
B_HEADER_ANCHOR = ""
B_HEADER_REPL   = ""

# 1) New component ------------------------------------------------------------
write_file("components/vendor/Cabinet.tsx", B_CABINET_TSX,
           marker="export default function Cabinet")

# 2) Cabinet CSS appended to globals.css --------------------------------------
append_once("app/globals.css", B_CABINET_CSS,
            marker="=== DREAM CABINET (ported")

# 3) API layer: fetchCabinet + types ------------------------------------------
insert_before("lib/vendor/api/vendor.ts", d(B_VENDOR_ANCHOR), d(B_VENDOR_INSERT),
              "vendor.ts: fetchCabinet + types")

# 4) theme.ts -----------------------------------------------------------------
edit("lib/vendor/theme.ts",
     "  isLight: boolean;\n}",
     "  isLight: boolean;\n  label: string;\n  accentText: string;\n}",
     "theme.ts: interface fields")
edit("lib/vendor/theme.ts",
     "  isLight:    false,\n};",
     "  isLight:    false,\n  label:      '#E0BC6E',\n  accentText: '#C9A84C',\n};",
     "theme.ts: DARK fields")
edit("lib/vendor/theme.ts",
     "  isLight:    true,\n};",
     "  isLight:    true,\n  label:      '#7A3828',\n  accentText: '#7A3828',\n};",
     "theme.ts: LIGHT fields")
insert_before("lib/vendor/theme.ts",
     "export function useThemeTokens(): ThemeTokens {",
     d(B_FLAIR_BLOCK),
     "theme.ts: FLAIR token set")
edit("lib/vendor/theme.ts",
     "  return theme === 'light' ? LIGHT : DARK;",
     "  return theme === 'light' ? LIGHT : theme === 'flair' ? FLAIR : DARK;",
     "theme.ts: useThemeTokens flair branch")

# 5) ThemeContext.tsx ---------------------------------------------------------
edit("lib/vendor/ThemeContext.tsx",
     "import { DARK, LIGHT, type ThemeTokens } from './theme';",
     "import { DARK, LIGHT, FLAIR, type ThemeTokens } from './theme';",
     "ThemeContext: import FLAIR")
edit("lib/vendor/ThemeContext.tsx",
     "  r.setProperty('--atelier-label',        t.isLight ? '#7A3828' : '#E0BC6E');",
     "  r.setProperty('--atelier-label',        t.label);",
     "ThemeContext: label var")
edit("lib/vendor/ThemeContext.tsx",
     "  r.setProperty('--atelier-accent-text',  t.isLight ? '#7A3828' : '#C9A84C');",
     "  r.setProperty('--atelier-accent-text',  t.accentText);",
     "ThemeContext: accent-text var")
edit("lib/vendor/ThemeContext.tsx",
     "  document.documentElement.style.background = t.isLight ? '#F5F2EE' : '';\n  document.body.style.background = t.isLight ? '#F5F2EE' : '';",
     "  const __bg = t.isLight ? '#F5F2EE' : (t.pageBg === '#090d17' ? '#090d17' : '');\n  document.documentElement.style.background = __bg;\n  document.body.style.background = __bg;",
     "ThemeContext: body bg (flair-aware)")
edit("lib/vendor/ThemeContext.tsx",
     "  const [currentTheme, setCurrentTheme] = useState<'dark' | 'light'>('dark');",
     "  const [currentTheme, setCurrentTheme] = useState<'dark' | 'light' | 'flair'>('dark');",
     "ThemeContext: currentTheme type")
edit("lib/vendor/ThemeContext.tsx",
     "  function applyTheme(theme: 'dark' | 'light') {\n    const t = theme === 'light' ? LIGHT : DARK;\n    setTokens(t);\n    setCurrentTheme(theme);\n    document.documentElement.classList.toggle('theme-light', theme === 'light');\n    // Apply base vars first\n    applyCSSVars(t);\n  }",
     "  function applyTheme(theme: 'dark' | 'light' | 'flair') {\n    const t = theme === 'flair' ? FLAIR : theme === 'light' ? LIGHT : DARK;\n    setTokens(t);\n    setCurrentTheme(theme);\n    document.documentElement.classList.toggle('theme-light', theme === 'light');\n    document.documentElement.classList.toggle('theme-flair', theme === 'flair');\n    // Apply base vars first\n    applyCSSVars(t);\n  }",
     "ThemeContext: applyTheme 3-state")
edit("lib/vendor/ThemeContext.tsx",
     "      const stored = localStorage.getItem(KEY) as 'dark' | 'light' | null;\n      applyTheme(stored === 'light' ? 'light' : 'dark');",
     "      const stored = localStorage.getItem(KEY) as 'dark' | 'light' | 'flair' | null;\n      applyTheme(stored === 'light' ? 'light' : stored === 'flair' ? 'flair' : 'dark');",
     "ThemeContext: initial read")
edit("lib/vendor/ThemeContext.tsx",
     "      if (e.key === KEY) applyTheme((e.newValue as 'dark' | 'light') ?? 'dark');",
     "      if (e.key === KEY) applyTheme((e.newValue as 'dark' | 'light' | 'flair') ?? 'dark');",
     "ThemeContext: storage handler")
edit("lib/vendor/ThemeContext.tsx",
     "      const isLight = html.classList.contains('theme-light');\n      const t = isLight ? LIGHT : DARK;\n      setTokens(t);\n      setCurrentTheme(isLight ? 'light' : 'dark');\n      applyCSSVars(t);",
     "      const isLight = html.classList.contains('theme-light');\n      const isFlair = html.classList.contains('theme-flair');\n      const t = isFlair ? FLAIR : isLight ? LIGHT : DARK;\n      setTokens(t);\n      setCurrentTheme(isFlair ? 'flair' : isLight ? 'light' : 'dark');\n      applyCSSVars(t);",
     "ThemeContext: observer 3-state")

# 6) hooks/useTheme.ts: overwrite with 3-state version ------------------------
write_file("hooks/vendor/useTheme.ts", B_USETHEME_TS,
           marker="export type Theme = 'dark' | 'light' | 'flair';")

# 7) Header.tsx ---------------------------------------------------------------
edit("components/vendor/Header.tsx",
     "  const [theme, toggleTheme] = useTheme();",
     "  const [theme, , setThemeMode] = useTheme();",
     "Header: destructure setThemeMode")
edit("components/vendor/Header.tsx",
     d(B_HEADER_ANCHOR), d(B_HEADER_REPL),
     "Header: 3-way Display picker")

# 8) app/vendor/page.tsx ------------------------------------------------------
edit("app/vendor/page.tsx",
     "import { OnboardingOverlay } from '@/components/vendor/OnboardingOverlay';",
     "import { OnboardingOverlay } from '@/components/vendor/OnboardingOverlay';\nimport Cabinet from '@/components/vendor/Cabinet';",
     "page.tsx: import Cabinet")
edit("app/vendor/page.tsx",
     "    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0, position: 'relative' }}>",
     "    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', minHeight: 0, position: 'relative' }}>\n      <Cabinet vendorId={vendorId} />",
     "page.tsx: mount Cabinet")

print()
print("==> writer done: " + str(changed) + " change(s) applied, " + str(skipped) + " skipped.")
if skipped:
    print("    NOTE: one or more anchors were missing/duplicated. Nothing was")
    print("    corrupted. Re-clone the live repo and re-run, or report the SKIP lines.")
sys.exit(0)
